 const sampling = @import("sampling.zig");

 const ops_mod = @import("ops.zig");
+const head_scored = @import("draft_head_scored.zig");
 var conf_pack_noted = std.atomic.Value(bool).init(false);
+var head_scored_noted = std.atomic.Value(bool).init(false);

 const Engine = prompt.Engine;
 const Chunk = prompt.Chunk;
@@ -143,17 +145,19 @@ pub const Item = struct { slot: usize, taps: u64, n: usize, start: usize };
 pub const Keyed = struct { seeds: []const u64, temps: []const f64 };

 /// The Markov loop's pre-step hook: step i's logits block row of every stream plus T * gumbel (each step reads its own
-/// block row of `local`, so no noise reaches another step).
+/// block row of `local`, so no noise reaches another step). `rs` is a stream's logits rows (TF_DS_DRAFT_HEAD_SCORED
+/// packs them: the scored rows are steps apart, not the block's n).
 const NoiseTap = struct {
     e: *const Engine,
     dr: *const Drafter,
     n: usize,
+    rs: usize,

     fn run(ctx: *anyopaque, step: usize) anyerror!void {
         const x: *NoiseTap = @ptrCast(@alignCast(ctx));
         const mk = x.dr.mk;
         const lw = mk.rowCols();
-        try x.e.ops.keyedNoise(x.e.s, x.dr.local + 4 * step * lw, x.dr.bn * lw, lw, mk.col0(), x.dr.nz, step, x.n);
