+        try x.e.ops.specClean(x.e.s, dr.local + 4 * step * lw, x.rs * lw, lw, dr.nz, dr.out + 8 * step, x.ts, mk.slot, mk.cache, dr.msc.stage, mk.cols, dr.sq + 4 * step * dr.sq_w, dr.n * dr.sq_w, x.n);
+        try x.e.ops.keyedNoise(x.e.s, dr.local + 4 * step * lw, x.rs * lw, lw, mk.col0(), dr.nz, step, x.n);
     }
 };

@@ -673,22 +680,40 @@ pub const Drafter = struct {
         const S = dr.ds.blocks.len;
         try Probe.check(probe, .stages_h, S, h);
         try Probe.check(probe, .stages_pre, S, pre);
-        // the head on every row (this rank's columns: the Markov loop scores them without a gather)
-        try tri_basic.collapse(t, h, pre, dr.xc, R, d);
-        try tri_basic.rmsnorm(t, dr.xc, d, dr.ds.norm, dr.xn, d, c.eps, R, d);
-        try prompt.grouped(e, ch, R, &.{e.w.head}, &.{dr.xn}, &.{d}, &.{dr.local}, &.{e.w.head.n}, &.{.f32});
+        // the head (this rank's columns: the Markov loop scores them without a gather). TF_DS_DRAFT_HEAD_SCORED: a
+        // pass scores only its first `steps` block rows a stream, so the collapse, the norm and the head project just
+        // those, packed rows i * steps + s (the full rows are i * n + s). Every reader below indexes a stream's rows
+        // with the one stride `lrow`, so both layouts hand it the same values; the kit's per-row collapse/norm and the
+        // head's glinear (a plan per layer shape: "a layer keeps one reduction for every row count") are row-count
+        // invariant, so the scored rows stay bit-identical. A checked pass (a probe hashes the whole logits buffer
+        // against the recording), a 2D drafter (its logits rows are lg_w columns) and a pass scoring every row run
+        // what they ran without the switch.
+        const scored = head_scored.scored(e.ops.draft_head_scored, probe != null, e.two != null, steps, n);
+        const lrow: usize = if (scored) steps else n; // a stream's rows in xc / xn / local
+        if (scored) {
+            if (!head_scored_noted.swap(true, .monotonic)) std.log.info("dsv41: TF_DS_DRAFT_HEAD_SCORED: the head projects only the scored rows (first at {d} streams x {d} steps)", .{ N, steps });
+            for (0..N) |i| {
+                try tri_basic.collapse(t, h + i * n * c.hc * d * 2, pre + i * n * c.hc * 4, dr.xc + i * steps * d * 2, steps, d);
+            }
+            try tri_basic.rmsnorm(t, dr.xc, d, dr.ds.norm, dr.xn, d, c.eps, N * steps, d);
+            try prompt.grouped(e, ch, N * steps, &.{e.w.head}, &.{dr.xn}, &.{d}, &.{dr.local}, &.{e.w.head.n}, &.{.f32});
+        } else {
+            try tri_basic.collapse(t, h, pre, dr.xc, R, d);
+            try tri_basic.rmsnorm(t, dr.xc, d, dr.ds.norm, dr.xn, d, c.eps, R, d);
+            try prompt.grouped(e, ch, R, &.{e.w.head}, &.{dr.xn}, &.{d}, &.{dr.local}, &.{e.w.head.n}, &.{.f32});
+        }
         try Probe.check(probe, .local, S, dr.local);
         // the Markov loop: out [N, steps + 1], each stream's last token first
         const ts = steps + 1;
         var g: MarkovGather = .{ .e = e, .dst = dr.mg };
-        var nt: NoiseTap = .{ .e = e, .dr = dr, .n = N };
+        var nt: NoiseTap = .{ .e = e, .dr = dr, .n = N, .rs = lrow };
         // TF_DS_SPEC_SAMPLE: a noisy pass's noise goes in after the step's _bias, with the clean scores before it (the
         // same launches on every rank: `noisy` is the pass frame's, the switch the pair's)
-        var st: SpecTap = .{ .e = e, .dr = dr, .n = N, .ts = ts };
