+        try dr.mk.stepsTapped(t, dr.local, dr.out, ts, N, lrow, steps, dr.msc, .{ .ctx = &g, .run = MarkovGather.run }, noise, mid);
         try Probe.check(probe, .markov, S, dr.out);
