//! TF_DS_DRAFT_HEAD_SCORED (off by default): the drafter's vocab head projects only the rows a pass scores. A pass
//! runs `n` block rows a stream (blockRows(steps)) but the Markov loop and the confidence head read only the first
//! `steps` of them, so the on path packs those rows while collapsing the hidden state (packed row i * steps + s of
//! xc / xn / local, what the full path computes at i * n + s), and the head is one GEMM of N * steps rows instead of
//! N * n. The readers index a stream's rows with one stride (`lrow`: the packed steps, or the full n), so both
//! layouts give every reader the same values at the rows it reads. Pure: no cuda import; the call site is
//! Drafter.body, the switch's field Ops.draft_head_scored. A malformed switch refuses startup.
const std = @import("std");

pub const env_name: [:0]const u8 = "TF_DS_DRAFT_HEAD_SCORED";

/// The switch's value: unset, "" or "0" off; "1" on; anything else is a refusal to start (the message is on stderr).
pub fn parse(text: ?[]const u8) ?bool {
    const t = text orelse return false;
    if (t.len == 0 or std.mem.eql(u8, t, "0")) return false;
    if (std.mem.eql(u8, t, "1")) return true;
    std.debug.print("{s}: expected 1 or 0\n", .{env_name});
    return null;
}

pub fn fromText(text: ?[]const u8) error{BadDraftHeadScored}!bool {
    return parse(text) orelse error.BadDraftHeadScored;
}

// -- host reference -------------------------------------------------------------------------------------------------

/// A pass's rows: `streams` streams of `n` block rows, the first `steps` of each scored (steps <= n).
pub const Dims = struct { streams: usize, steps: usize, n: usize };

/// The full path's row of stream `stream`'s step `step` in xc / xn / local (and the row of h / pre the collapse of
/// that step reads).
pub fn srcRow(m: Dims, stream: usize, step: usize) usize {
    std.debug.assert(stream < m.streams and step < m.steps and m.steps <= m.n);
    return stream * m.n + step;
}

/// The packed row the on path computes it at: one stream's scored rows are contiguous.
pub fn packRow(m: Dims, stream: usize, step: usize) usize {
    std.debug.assert(stream < m.streams and step < m.steps and m.steps <= m.n);
    return stream * m.steps + step;
}

/// The row a downstream reader indexes with a stream stride `lrow` (the Markov loop's _score rows at step `step`, the
/// noise and spec hooks' rows, and the confidence packer's xc rows): step + stream * lrow. The on path passes
/// lrow = steps (packed), the full path lrow = n.
pub fn readRow(lrow: usize, stream: usize, step: usize) usize {
    return step + stream * lrow;
}

/// Whether the pass takes the on path: the switch on, no checker (Probe reads the whole logits buffer against the
/// recording), no 2D drafter (its logits rows are lg_w columns, draft2d.zig), and strictly fewer scored rows than
/// block rows (a pass that scores every row runs exactly what it ran without the switch).
pub fn scored(on: bool, checked: bool, twod: bool, steps: usize, n: usize) bool {
    return on and !checked and !twod and steps >= 1 and steps < n;
}

// -- tests -----------------------------------------------------------------------------------------------------------

test "the switch parses its forms and nothing else" {
    try std.testing.expectEqual(@as(?bool, false), parse(null));
    try std.testing.expectEqual(@as(?bool, false), parse(""));
    try std.testing.expectEqual(@as(?bool, false), parse("0"));
    try std.testing.expectEqual(@as(?bool, true), parse("1"));
    try std.testing.expectEqual(@as(?bool, null), parse("2"));
    try std.testing.expectEqual(@as(?bool, null), parse("on"));
    try std.testing.expectEqual(@as(?bool, null), parse("01"));
    try std.testing.expectEqual(@as(bool, true), try fromText("1"));
    try std.testing.expectError(error.BadDraftHeadScored, fromText("2"));
}

test "the on path needs the switch, no checker, no 2D drafter and unscored rows" {
    try std.testing.expect(scored(true, false, false, 3, 5));
    try std.testing.expect(!scored(false, false, false, 3, 5)); // off
    try std.testing.expect(!scored(true, true, false, 3, 5)); // a checked pass keeps every row
    try std.testing.expect(!scored(true, false, true, 3, 5)); // the 2D drafter's rows
    try std.testing.expect(!scored(true, false, false, 5, 5)); // every row scored: the full path
    try std.testing.expect(!scored(true, false, false, 6, 6)); // TF_DS_DRAFT_BLOCK's widened pass
    try std.testing.expect(!scored(true, false, false, 0, 5)); // no steps
}

test "packed rows are bijective over the scored rows and are the rows the readers index" {
    // N 1..4, n 5..7, steps 1..n: the brief's row-selection matrix
    var cases: usize = 0;
    var shallow: usize = 0;
    for (1..5) |N| for (5..8) |n| for (1..n + 1) |steps| {
        const m: Dims = .{ .streams = N, .steps = steps, .n = n };
        var seen = std.mem.zeroes([4 * 8]bool);
        for (0..N) |i| for (0..steps) |s| {
            const p = packRow(m, i, s);
            try std.testing.expect(p < N * steps and !seen[p]);
            seen[p] = true;
            // the readers (Markov _score, the hooks, the confidence packer) index it with the packed stride
            try std.testing.expectEqual(p, readRow(steps, i, s));
            // the full path computes the same value at a different row
            try std.testing.expectEqual(i * n + s, srcRow(m, i, s));
        };
        cases += 1;
        if (steps < n) shallow += 1;
    };
    try std.testing.expectEqual(@as(usize, 72), cases);
    try std.testing.expectEqual(@as(usize, 60), shallow);
}

