/// TF_DS_SPEC_SAMPLE's step hook between the step's _bias and _score (tri_markov.stepsTapped's mid): every sampled
/// stream's clean scores (its logits plus the Markov bias row _score adds: the cached row of the token the step reads,
/// else the step's staging row) and their normaliser partials into `sq` (tf_ds_spec_clean_kernel), then NoiseTap's
/// keyed noise under the draft key, so each draft is a draw from softmax(clean / T) and the verify gathers its numbers.
/// `sq` keeps its own row layout (row stream * n + step: lanes' spec gather reads it), so only the logits stride
/// follows the packing.
const SpecTap = struct {
    e: *const Engine,
    dr: *const Drafter,
    n: usize,
    ts: usize,
    rs: usize,

    fn run(ctx: *anyopaque, step: usize) anyerror!void {
        const x: *SpecTap = @ptrCast(@alignCast(ctx));
        const dr = x.dr;
        const mk = dr.mk;
        const lw = mk.rowCols();
        try x.e.ops.specClean(x.e.s, dr.local + 4 * step * lw, x.rs * lw, lw, dr.nz, dr.out + 8 * step, x.ts, mk.slot, mk.cache, dr.msc.stage, mk.cols, dr.sq + 4 * step * dr.sq_w, dr.n * dr.sq_w, x.n);
        try x.e.ops.keyedNoise(x.e.s, dr.local + 4 * step * lw, x.rs * lw, lw, mk.col0(), dr.nz, step, x.n);
    }
};

/// TF_DS_SPEC_SAMPLE: the most rows a verify speculates (every stream's held drafts) and the most elements its gather
/// takes a row: the target's candidates and the draft, then the row's normaliser partials.
pub const spec_rows = max_streams * max_block;
pub const spec_row_elems = sampling.max_candidates + 1 + 2 * ops_mod.spec_parts;
pub const spec_elems = spec_rows * spec_row_elems;

/// The per-step gather of the Markov loop's bests: [world, rows, 4] fp32 into dst.
const MarkovGather = struct {
    e: *const Engine,
    dst: u64,

    fn run(ctx: *anyopaque, send: u64, rows: usize) anyerror!u64 {
        const g: *MarkovGather = @ptrCast(@alignCast(ctx));
        try g.e.gatherF32(send, g.dst, rows * 4);
        return g.dst;
    }
};

