        const smem: u32 = @intCast(pf.wk * @min(m, 8) * 128 * 4);
        try cuda.launch.launch(f, .{ .grid = .{ .x = @intCast(blocks) }, .block = .{ .x = pf.wk * 32 }, .shared = smem, .pdl = pdl }, stream, &args);
